49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /** Maximum number of owners permitted in a single city; the create is rejected at this count. */
59	    private static final int CITY_CAPACITY = 50;
60	
61	    /** Maximum number of owners that may be created on a single day (by registrationDate); the
62	     * create is rejected once this many owners already carry today's registration date. */
63	    private static final int DAILY_REGISTRATION_LIMIT = 100;
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        HttpHeaders headers = new HttpHeaders();
112	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
113	        // The effective registration date (supplied, or the server date when omitted) must fall on
114	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
115	        // registration date — the stored value, the per-day limit below and the membership number —
116	        // uses this adjusted date.
117	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
118	        owner.setRegistrationDate(effectiveDate);
119	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
120	        // further creates for that day with 429 Too Many Requests.
121	        if (this.clinicService.countOwnersRegisteredOn(effectiveDate) >= DAILY_REGISTRATION_LIMIT) {
122	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
123	        }
124	        if (this.clinicService.isTelephoneInUse(owner.getTelephone())) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        // Per-city capacity: a city that already holds the maximum number of owners is full.
128	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
129	            return new ResponseEntity<>(HttpStatus.CONFLICT);
130	        }
131	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
132	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress());
133	        if (householdInUse) {
134	            if (!sharesHousehold) {
135	                return new ResponseEntity<>(HttpStatus.CONFLICT);
136	            }
137	            // Joining an existing household: assign the shared, stable household identifier to
138	            // the new owner (and back-fill the existing member(s)).
139	            this.clinicService.assignHousehold(owner);
140	        }
141	        owner.setNamesakeCount(
142	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
143	        this.clinicService.saveOwner(owner);
144	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
145	        headers.setLocation(UriComponentsBuilder.newInstance()
146	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
147	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
153	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
154	        if (currentOwner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        currentOwner.setAddress(ownerFieldsDto.getAddress());
158	        currentOwner.setCity(ownerFieldsDto.getCity());
159	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
160	        currentOwner.setLastName(ownerFieldsDto.getLastName());
161	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
162	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
163	        this.clinicService.saveOwner(currentOwner);
164	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Transactional
169	    @Override
170	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
171	        Owner owner = this.clinicService.findOwnerById(ownerId);
172	        if (owner == null) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        this.clinicService.deleteOwner(owner);
176	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
182	        Owner owner = this.clinicService.findOwnerById(ownerId);
183	        if (owner == null) {
184	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
185	        }
186	        HttpHeaders headers = new HttpHeaders();
187	        Pet pet = petMapper.toPet(petFieldsDto);
188	        owner.setId(ownerId);
189	        pet.setOwner(owner);
190	        pet.getType().setName(null);
191	        this.clinicService.savePet(pet);
192	        PetDto petDto = petMapper.toPetDto(pet);
193	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
194	            .buildAndExpand(pet.getId()).toUri());
195	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
196	    }
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
201	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
202	        if (currentOwner != null) {
203	            Pet currentPet = this.clinicService.findPetById(petId);
204	            if (currentPet != null) {
205	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
206	                currentPet.setName(petFieldsDto.getName());
207	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
208	                this.clinicService.savePet(currentPet);
209	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
210	            }
211	        }
212	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	    }
214	
215	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
216	    @Override
217	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
218	        HttpHeaders headers = new HttpHeaders();
219	        Visit visit = visitMapper.toVisit(visitFieldsDto);
220	        Pet pet = new Pet();
221	        pet.setId(petId);
222	        visit.setPet(pet);
223	        this.clinicService.saveVisit(visit);
224	        VisitDto visitDto = visitMapper.toVisitDto(visit);
225	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
226	            .buildAndExpand(visit.getId()).toUri());
227	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
228	    }
229	
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
234	        Owner owner = this.clinicService.findOwnerById(ownerId);
235	        if (owner != null) {
236	            Pet pet = owner.getPet(petId);
237	            if (pet != null) {
238	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
239	            }
240	        }
241	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
242	    }
243	}
