29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "customer_code")
61	    private String customerCode;
62	
63	    @Column(name = "household_id")
64	    private String householdId;
65	
66	    @Column(name = "namesake_count")
67	    private Integer namesakeCount;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    public Integer getNamesakeCount() {
129	        return this.namesakeCount;
130	    }
131	
132	    public void setNamesakeCount(Integer namesakeCount) {
133	        this.namesakeCount = namesakeCount;
134	    }
135	
136	    /**
137	     * When no registration date is supplied, default it to the server's current date, then roll
138	     * the effective date forward onto a business day: a Saturday or Sunday becomes the following
139	     * Monday. Running on {@link PrePersist} keeps both invariants true for every create path
140	     * (any controller, bulk import or test fixture) rather than a single entry point. The roll is
141	     * idempotent, so a date already adjusted by a caller is left unchanged.
142	     */
143	    @PrePersist
144	    protected void onCreate() {
145	        this.registrationDate = BusinessDays.effectiveRegistrationDate(this.registrationDate);
146	    }
147	
148	    protected Set<Pet> getPetsInternal() {
149	        if (this.pets == null) {
150	            this.pets = new HashSet<>();
151	        }
152	        return this.pets;
153	    }
154	
155	    protected void setPetsInternal(Set<Pet> pets) {
156	        this.pets = pets;
157	    }
158	
159	    public List<Pet> getPets() {
160	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
161	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
162	        return Collections.unmodifiableList(sortedPets);
163	    }
164	
165	    public void setPets(List<Pet> pets) {
166	        this.pets = new HashSet<>(pets);
167	    }
168	
169	    public void addPet(Pet pet) {
170	        getPetsInternal().add(pet);
171	        pet.setOwner(this);
172	    }
173	
174	    /**
175	     * Return the Pet with the given name, or null if none found for this Owner.
176	     *
177	     * @param name to test
178	     * @return true if pet name is already in use
179	     */
180	    public Pet getPet(String name) {
181	        return getPet(name, false);
182	    }
183	
184	    /**
185	     * Return the Pet with the given name, or null if none found for this Owner.
186	     *
187	     * @param name to test
188	     * @return true if pet name is already in use
189	     */
190	    public Pet getPet(String name, boolean ignoreNew) {
191	        name = name.toLowerCase();
192	        for (Pet pet : getPetsInternal()) {
193	            if (!ignoreNew || !pet.isNew()) {
194	                String compName = pet.getName();
195	                compName = compName.toLowerCase();
196	                if (compName.equals(name)) {
197	                    return pet;
198	                }
199	            }
200	        }
201	        return null;
202	    }
203	
204	    public Pet getPet(Integer petId) {
205	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
206	    }
207	
208	    @Override
209	    public String toString() {
210	        return new ToStringCreator(this)
211	
212	            .append("id", this.getId())
213	            .append("new", this.isNew())
214	            .append("lastName", this.getLastName())
215	            .append("firstName", this.getFirstName())
216	            .append("address", this.address)
217	            .append("city", this.city)
218	            .append("telephone", this.telephone)
219	            .append("email", this.email)
220	            .append("registrationDate", this.registrationDate)
221	            .append("customerCode", this.customerCode)
222	            .append("householdId", this.householdId)
223	            .append("namesakeCount", this.namesakeCount)
224	            .toString();
225	    }
226	}
