3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Rolls a calendar date forward onto a business day.
8	 *
9	 * <p>A business day is any day that is not a Saturday or Sunday. When the supplied date already
10	 * falls on a weekday it is returned unchanged; when it falls on a Saturday or Sunday it is rolled
11	 * forward to the following Monday. The operation is idempotent: feeding it an already-adjusted
12	 * (weekday) value returns that same value.
13	 */
14	public final class BusinessDays {
15	
16	    private BusinessDays() {
17	    }
18	
19	    /**
20	     * Return {@code date} when it falls on a weekday, or the next Monday when it falls on a
21	     * Saturday or Sunday. Returns {@code null} when the input is {@code null}.
22	     */
23	    public static LocalDate rollToBusinessDay(LocalDate date) {
24	        if (date == null) {
25	            return null;
26	        }
27	        DayOfWeek day = date.getDayOfWeek();
28	        if (day == DayOfWeek.SATURDAY) {
29	            return date.plusDays(2);
30	        }
31	        if (day == DayOfWeek.SUNDAY) {
32	            return date.plusDays(1);
33	        }
34	        return date;
35	    }
36	
37	    /**
38	     * Resolve the effective registration date: the supplied date, or the server's current date
39	     * when {@code null}, rolled forward onto a business day. This is the single definition of the
40	     * "default-to-now, then roll" policy shared by the create controller (which needs the value
41	     * eagerly) and the {@code @PrePersist} backstop. Idempotent for an already-adjusted value.
42	     */
43	    public static LocalDate effectiveRegistrationDate(LocalDate supplied) {
44	        return rollToBusinessDay(supplied != null ? supplied : LocalDate.now());
45	    }
46	}
