250	    /**
251	     * Build a {@code customerCode} of the form {@code <CITY3>-<LAST3>-<NNNN>}: the upper-cased
252	     * first three letters of the owner's city, a hyphen, the upper-cased first three letters of
253	     * the owner's last name, a hyphen, and a per-city 4-digit zero-padded sequence equal to one
254	     * more than the number of owners already registered in that city (e.g. {@code TOW-SMI-0007}).
255	     */
256	    private String generateCustomerCode(Owner owner) {
257	        String city = owner.getCity() == null ? "" : owner.getCity();
258	        int sequence = (int) ownerRepository.findAll().stream()
259	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
260	            .count() + 1;
261	        return String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence);
