264	    /**
265	     * The upper-cased first three letters of {@code value} (fewer if it is shorter), treating a
266	     * {@code null} value as empty. This is the shared rule behind both the CITY3 and LAST3
267	     * segments of a {@code customerCode}.
268	     */
269	    private static String prefix3(String value) {
270	        String s = value == null ? "" : value;
271	        return s.substring(0, Math.min(3, s.length())).toUpperCase();
