292	    @Override
293	    @Transactional(readOnly = true)
294	    public boolean isHouseholdInUse(String lastName, String address) throws DataAccessException {
295	        String normalizedLastName = normalizeForComparison(lastName);
296	        String normalizedAddress = normalizeForComparison(address);
297	        if (normalizedLastName == null || normalizedAddress == null) {
298	            return false;
299	        }
300	        return ownerRepository.findAll().stream()
301	            .anyMatch(existing -> inHousehold(existing, normalizedLastName, normalizedAddress));
302	    }
303	
304	    /**
305	     * Canonicalize a free-text value for equality comparison: trim, collapse every run of
306	     * whitespace to a single space and lower-case the result, so values that differ only in
307	     * letter case or incidental whitespace are treated as equal. Shared by the household
308	     * (last name / address) and per-city matching rules.
309	     */
310	    private String normalizeForComparison(String value) {
311	        if (value == null) {
312	            return null;
313	        }
314	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
315	    }
316	
317	    /**
318	     * Single definition of household membership: an owner belongs to the household identified by
319	     * the given already-normalized last name and address when its own normalized last name and
320	     * address match. Keeping this in one place means the household-equality rule is changed once.
321	     */
322	    private boolean inHousehold(Owner existing, String normalizedLastName, String normalizedAddress) {
323	        return normalizedLastName.equals(normalizeForComparison(existing.getLastName()))
324	            && normalizedAddress.equals(normalizeForComparison(existing.getAddress()));
325	    }
